#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    int max_val = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (a[i] > max_val) {
            max_val = a[i];
        }
    }

    int phases = 0;

    while (true) {
        int min_val = a[0];
        for (int i = 1; i < n; ++i) {
            if (a[i] < min_val) {
                min_val = a[i];
            }
        }

        if (min_val == max_val) {
            break;
        }

        int i = 0;
        while (i < n) {
            if (a[i] == min_val) {
                int j = i;
                while (j < n && a[j] == min_val) {
                    a[j]++;
                    j++;
                }
                phases++;
                i = j;
            } else {
                i++;
            }
        }
    }

    cout << phases << "\n";

    return 0;
}
